//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_PortStatus_ATV6xx
//	CREATOR:		Helgevold - Ruben Byman                                                                                                                                                                                                                                                              
// REQ: 			SNMP communication & Schneider ATV6xx VFD                                                                                                                                                                                                                                                                                                               
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-03-30		Ruben Byman			Initial release
//
//===============================================================================================================================
//
//		FUNCTIONALITY:
//		Uses SNMP to check port status of both Ethernet/IP ports of Schneider ATV6xx
//		Outputs Sts_PortError if any of the ports are not OK
//		
//===============================================================================================================================

(*************************************************************************
 *	ASSIGNS TOKEN
 *************************************************************************)
 
IF TokenID = -1 THEN
	FOR TokenID:=0 TO DINT_TO_UINT(UPPER_BOUND(Ext_Telegram.Token_Static, 1)) DO
		IF NOT Ext_Telegram.Token_Static[TokenID] THEN
			Ext_Telegram.Token_Static[TokenID]:=TRUE;
			EXIT;
		END_IF;
	END_FOR;
END_IF;

(*************************************************************************
 *	TIMEOUT (If too long time in state)
 *************************************************************************)
 
IF Ext_Telegram.Token_Active = TokenID THEN
	Wrk_TimeInState:=ADD_TIME(In1:=Wrk_TimeInState, In2:=GetMyTaskInterval());
	IF Wrk_State <> Wrk_SampleState THEN
	Wrk_TimeInState:=TIME#0ms;
	Wrk_SampleState:= Wrk_State;
	END_IF;
ELSE
	Wrk_TimeInState:=TIME#0ms;
	Wrk_State:= 0;
END_IF;

IF Wrk_TimeInState > Ext_Telegram.Timeout THEN
	Wrk_ErrorCode := 16#8000000; // Timeout error code
	Inc(Ext_Telegram.Token_Active);
	Wrk_TimeInState:=TIME#0ms;
END_IF;

(*************************************************************************
 *	CASE FOR REQUEST & DATA SEND
 *************************************************************************)

CASE Wrk_State OF
	
	0: // Wait for turn
		IF Ext_Telegram.Token_Active = TokenID THEN
			
			//Setting common parameters
			Ext_Telegram.RemotePort:=161;
			Ext_Telegram.RemoteIP:=Cfg_IPAdr;
			Ext_Telegram.Community:='public';
			Ext_Telegram.SNMP_Ver:=0;
			Wrk_State := 10;
			
		END_IF;
	
	10: // Read port 1 status
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:='1.3.6.1.2.1.2.2.1.8.1';
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 11;
			
		END_IF;
		
	11: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Port_State1_Raw := Ext_Telegram.ResponseValue=1;
			Wrk_CommStatus := Ext_Telegram.Comm_OK;
			Wrk_State := 20;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Port_State1_Raw := FALSE;
			Wrk_CommStatus := Ext_Telegram.Comm_OK;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
	
	20: // Read port 2 status
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:='1.3.6.1.2.1.2.2.1.8.2';
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 21;
			
		END_IF;
		
	21: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Port_State2_Raw := Ext_Telegram.ResponseValue=1;
			Wrk_State := 1000;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Port_State2_Raw:=FALSE;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;

	1000: //Completed OK
		Inc(Ext_Telegram.Token_Active);
		Wrk_State := 0;
		Wrk_SNMP_Error :=FALSE;
		Ext_Telegram.Execute := FALSE;
		Wrk_Successes := Wrk_Successes + 1;
	
	1001: //General error
		Inc(Ext_Telegram.Token_Active);
		Wrk_State := 0;
		Wrk_SNMP_Error :=TRUE;
		Wrk_Errors := Wrk_Errors + 1;
		Wrk_ErrorCode := Ext_Telegram.ErrorCode;
		Ext_Telegram.Execute := FALSE;
		
END_CASE;

(*************************************************************************
 *	PERFORMING LOGIC
 *************************************************************************)
 
//Communication OK
TOF_CommOK(In:=Wrk_CommStatus, PT:=T#5s);

(*************************************************************************
 *	UPDATING OUTPUTS
 *************************************************************************)
 
//Block
Sts_PortError := NOT Wrk_Port_State1_Raw OR NOT Wrk_Port_State2_Raw;
Sts_CommOK := NOT TOF_CommOK.Q;
Sts_Error := Wrk_SNMP_Error;
